const fs=require('node:fs');
function run(input) {
  if(input.action==='encode') return Buffer.from(input.text,'utf8').toString('base64');
  if(input.action==='isArray') return Array.isArray(input.value);
  if(input.action==='exists') return new Promise(resolve=>resolve(fs.existsSync(input.path)));
  throw Error('action');
}
module.exports={run};
